-- Objects stacked on each other (Discord "Bugs 2", 61881, item 68: "some objects are stacked on each other", no place given).
-- A read-only check on dev (af59, 2026-11-21) of the starting zones of his characters (Tirisfal, Mulgore, Durotar) found the
-- same object entry spawned two or more times within 1 yd. This removes the extra copies and keeps the oldest spawn of each:
--  - Campfire 2061: two camps in Tirisfal (1309 1212 and 1866 1563) had 2-3 fires each on one spot.
--  - Cactus Apple 171938 in Durotar (-315.8 -4444.2): two on one spot.
--  - Holiday decorations at exactly the same spot (distance 0): G_Pumpkin_01 180405, Horde Bell 175885, Haybail 02 180038,
--    Bonfire 178571. Each was imported twice; only the copy goes, with its game_event row.
-- Left as they are: decorations that are near each other on purpose (mugs, goblets, bats, candles: different spots), pooled
-- spawns, the Undercity quest objects 105174/105175 and the invisible DND traps 123334/123355.
-- Each copy is deleted only while an older spawn of the same entry that stays (not in this list) stands within 1 yd of it, so a
-- world without the duplicate loses nothing. The kept spawn must also match the copy in phase (PhaseId, PhaseGroup) and in its
-- holiday (the same game_event rows, or none on both), so no decoration leaves its holiday or stays up all year. Safe to run again.
DELETE d FROM `gameobject` d
  JOIN `gameobject` k ON k.`id` = d.`id` AND k.`map` = d.`map` AND k.`guid` < d.`guid`
   AND ABS(k.`position_x` - d.`position_x`) < 1 AND ABS(k.`position_y` - d.`position_y`) < 1 AND ABS(k.`position_z` - d.`position_z`) < 1
   AND k.`PhaseId` = d.`PhaseId` AND k.`PhaseGroup` = d.`PhaseGroup`
   AND COALESCE((SELECT GROUP_CONCAT(ek.`eventEntry` ORDER BY ek.`eventEntry`) FROM `game_event_gameobject` ek WHERE ek.`guid` = k.`guid`), '')
     = COALESCE((SELECT GROUP_CONCAT(ed.`eventEntry` ORDER BY ed.`eventEntry`) FROM `game_event_gameobject` ed WHERE ed.`guid` = d.`guid`), '')
   AND k.`guid` NOT IN (30012438,30018097,30018098,30018099,30018100,30018101,30018102,30018103,30020556,30020557,30033501,30033503,30033505,30044881,30044883,30044885,30045022,30055088,30330371,30330372,30330373,30330374,30330375,30330376,30330377,30330378,30330379,30330380,30330381,30330382,30330383,30330384,30330385,30330386,30330387,30330388,30330389,30330390,30330391,30330392,30330393,30330394,30330395,30330396,30330397,30330398,30330399,30330419,30330420,30330421,30330422,30330423,30330424,30330425,30330426,30330427,30330428,30330429,30330430,30330431,30330432,30330433,30330434,30330466,30330467,30330468,30330469,30330470,30330471,30330472,30330473,30330474,30330475,30330482,30365280,30365286,30365294)
  WHERE d.`guid` IN (30012438,30018097,30018098,30018099,30018100,30018101,30018102,30018103,30020556,30020557,30033501,30033503,30033505,30044881,30044883,30044885,30045022,30055088,30330371,30330372,30330373,30330374,30330375,30330376,30330377,30330378,30330379,30330380,30330381,30330382,30330383,30330384,30330385,30330386,30330387,30330388,30330389,30330390,30330391,30330392,30330393,30330394,30330395,30330396,30330397,30330398,30330399,30330419,30330420,30330421,30330422,30330423,30330424,30330425,30330426,30330427,30330428,30330429,30330430,30330431,30330432,30330433,30330434,30330466,30330467,30330468,30330469,30330470,30330471,30330472,30330473,30330474,30330475,30330482,30365280,30365286,30365294);
DELETE FROM `game_event_gameobject` WHERE `guid` IN (30012438,30018097,30018098,30018099,30018100,30018101,30018102,30018103,30020556,30020557,30033501,30033503,30033505,30044881,30044883,30044885,30045022,30055088,30330371,30330372,30330373,30330374,30330375,30330376,30330377,30330378,30330379,30330380,30330381,30330382,30330383,30330384,30330385,30330386,30330387,30330388,30330389,30330390,30330391,30330392,30330393,30330394,30330395,30330396,30330397,30330398,30330399,30330419,30330420,30330421,30330422,30330423,30330424,30330425,30330426,30330427,30330428,30330429,30330430,30330431,30330432,30330433,30330434,30330466,30330467,30330468,30330469,30330470,30330471,30330472,30330473,30330474,30330475,30330482,30365280,30365286,30365294)
  AND `guid` NOT IN (SELECT `guid` FROM `gameobject`);
